mapper.select:
SELECT if(count() = 0, '0', toString(max(Revision)))
FROM quasar_tracing.trace_archive_manifest
WHERE TraceId = #{traceId}

mapper.sql:
FROM quasar_tracing.trace_archive_spans s
INNER JOIN () m
    ON m.traceId = s.TraceId AND m.generation = toString(s.ArchiveGeneration)
WHERE m.state = 'ACTIVE'
  AND m.expiresAt > toUnixTimestamp64Milli(now64(3))
  AND s.Timestamp BETWEEN fromUnixTimestamp64Milli(#{from}) AND fromUnixTimestamp64Milli(#{to})
GROUP BY s.TraceId
HAVING 1 = 1

    AND has(groupUniqArray(s.ServiceName), #{service})


    AND argMin(s.SpanName, s.Timestamp) = #{operation}


    AND countIf(s.StatusCode = 'Error') > 0


    AND countIf(s.StatusCode = 'Error') = 0


    AND any(s.ResourceAttributes['deployment.environment.name']) = #{environment}


    AND (
        any(s.ResourceAttributes['service.namespace']) = #{namespace}
        OR any(s.ResourceAttributes['k8s.namespace.name']) = #{namespace}
    )


    AND any(s.ResourceAttributes['k8s.namespace.name']) = #{k8sNamespace}


    AND any(s.ResourceAttributes['k8s.pod.name']) = #{k8sPodName}


    AND any(s.ResourceAttributes['k8s.node.name']) = #{k8sNodeName}


    AND any(s.ResourceAttributes['service.instance.id']) = #{serviceInstanceId}


    AND countIf(





                        mapContains(s.ResourceAttributes, #{condition.key})


                        mapContains(s.ResourceAttributes, #{condition.key})
                        AND s.ResourceAttributes[#{condition.key}] = #{condition.value}


                        mapContains(s.ResourceAttributes, #{condition.key})
                        AND positionCaseInsensitive(
                            s.ResourceAttributes[#{condition.key}], #{condition.value}) > 0






                        mapContains(s.SpanAttributes, #{condition.key})


                        mapContains(s.SpanAttributes, #{condition.key})
                        AND s.SpanAttributes[#{condition.key}] = #{condition.value}


                        mapContains(s.SpanAttributes, #{condition.key})
                        AND positionCaseInsensitive(
                            s.SpanAttributes[#{condition.key}], #{condition.value}) > 0





    ) > 0


    AND countIf(
        1 = 1

            AND s.ServiceName = #{spanSelector.service}


            AND s.SpanName = #{spanSelector.operation}


            AND s.StatusCode = 'Error'


            AND s.StatusCode != 'Error'

    ) > 0


    AND (max(toUnixTimestamp64Nano(s.Timestamp) + s.Duration)
        - min(toUnixTimestamp64Nano(s.Timestamp))) >= #{minDurationNs}


    AND (max(toUnixTimestamp64Nano(s.Timestamp) + s.Duration)
        - min(toUnixTimestamp64Nano(s.Timestamp))) <= #{maxDurationNs}


    AND (positionCaseInsensitive(argMin(s.SpanName, s.Timestamp), #{q}) > 0
        OR position(s.TraceId, #{q}) > 0)
